// Capturamos el mensaje original desde tu nodo 'Input de Slack'
const original = $('Entrada multicanal').first().json.mensaje;

// Extraemos el texto crudo devuelto por la IA
const raw = $json.text ?? $json.output ?? $json.response ?? '';

let d;
try {
  // Limpiamos bloques markdown (```json ... ```) si la IA los incluyó y parseamos
  d = JSON.parse(String(raw).replace(/^```json\s*/i, '').replace(/```$/, '').trim());
} catch (e) {
  // Fallback seguro si falla el parseo
  d = { intent: 'UNKNOWN', confidence: 0, risk: 'HIGH' };
}

// Taxonomía permitida para GustoBot
const allowed = ['REGISTRAR_PEDIDO', 'CONSULTA_MENU', 'CONSULTA_DOCUMENTAL', 'RECLAMO_SOPORTE', 'UNKNOWN'];

// Validaciones y normalización
const intent = allowed.includes(d.intent) ? d.intent : 'UNKNOWN';
const confidence = Math.max(0, Math.min(1, Number(d.confidence ?? 0)));
const risk = ['LOW', 'MEDIUM', 'HIGH'].includes(d.risk) ? d.risk : 'HIGH';

// Retornamos el objeto normalizado para el Switch y los Workers
return [{
  json: {
    original_input: original,
    intent: intent,
    confidence: confidence,
    risk: risk
  }
}];

return $input.all().map(item => ({json:{
  timestamp:new Date().toISOString(),
  status:item.json.status ?? 'success',
  worker:item.json.worker ?? 'N/D',
  respuesta:item.json.respuesta ?? '',
  requires_human:Boolean(item.json.requires_human)
}}));

return $input.all().map(item => {
  const data = item.json;
  const ts = data.timestamp || new Date().toISOString();
  const worker = data.worker || 'UNKNOWN';
  const status = data.status || 'success';
  const hitl = data.requires_human ?? false;
  const logString = `[${ts}] | WORKER: ${worker} | STATUS: ${status} | HITL: ${hitl}`;

  return {
    json: {
      ...data,
      log: logString
    }
  };
});

