const original_input = String($input.first().json.original_input || '').trim();
const normalized = original_input.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
let query = original_input;
if (/\b(arrepent\w*|arrepient\w*|desist\w*|cancel\w*)\b/.test(normalized)) {
  query += '\nDerecho de arrepentimiento legal, cancelación de compra, devolución sin uso, plazo de 10 días corridos desde la entrega, artículo 34 de la Ley 24.240.';
}
return [{ json: { original_input, query } }];

const documents = $input.all()
  .map(item => item.json.document || item.json)
  .filter(document => typeof (document.pageContent || document.content) === 'string')
  .map(document => ({
    text: String(document.pageContent || document.content).trim(),
    metadata: document.metadata || {},
  }))
  .filter(document => document.text.length > 0);
const unique = [...new Map(documents.map(document => [document.text, document])).values()];
const context = unique.map((document, index) => {
  const metadata = document.metadata;
  const title = metadata.pdf && metadata.pdf.info && metadata.pdf.info.Title;
  const source = metadata.fuente || title || metadata.source || 'Documento de conocimiento';
  return `[Fragmento ${index + 1} | Fuente: ${source}]\n${document.text}`;
}).join('\n\n');
return [{
  json: {
    original_input: $('Preparar consulta documental').first().json.original_input,
    context,
    has_context: unique.length > 0,
    documents_count: unique.length,
  },
}];

function sha256(d){
const K=[],H=[];
for(let n=2;K.length<64;n++){let p=true;for(let i=2;i*i<=n;i++)if(n%i===0){p=false;break;}if(!p)continue;K.push(Math.floor((Math.cbrt(n)%1)*4294967296)>>>0);if(H.length<8)H.push(Math.floor((Math.sqrt(n)%1)*4294967296)>>>0);}
const len=d.length,total=((len+9+63)>>6)<<6;
const m=new Uint8Array(total);m.set(d);m[len]=0x80;
const dv=new DataView(m.buffer);
dv.setUint32(total-8,Math.floor(len/536870912));dv.setUint32(total-4,(len<<3)>>>0);
const w=new Uint32Array(64);
const r=(x,n)=>(x>>>n)|(x<<(32-n));
for(let o=0;o<total;o+=64){
for(let i=0;i<16;i++)w[i]=dv.getUint32(o+i*4);
for(let i=16;i<64;i++){const a=r(w[i-15],7)^r(w[i-15],18)^(w[i-15]>>>3),b=r(w[i-2],17)^r(w[i-2],19)^(w[i-2]>>>10);w[i]=(w[i-16]+a+w[i-7]+b)>>>0;}
let [A,B,C,D,E,F,G,I]=H;
for(let i=0;i<64;i++){const t1=(I+(r(E,6)^r(E,11)^r(E,25))+((E&F)^(~E&G))+K[i]+w[i])>>>0;const t2=((r(A,2)^r(A,13)^r(A,22))+((A&B)^(A&C)^(B&C)))>>>0;I=G;G=F;F=E;E=(D+t1)>>>0;D=C;C=B;B=A;A=(t1+t2)>>>0;}
H[0]=(H[0]+A)>>>0;H[1]=(H[1]+B)>>>0;H[2]=(H[2]+C)>>>0;H[3]=(H[3]+D)>>>0;H[4]=(H[4]+E)>>>0;H[5]=(H[5]+F)>>>0;H[6]=(H[6]+G)>>>0;H[7]=(H[7]+I)>>>0;
}
return H.map(x=>x.toString(16).padStart(8,'0')).join('');
}
const base = $('Normalizar archivo').all();
const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');
  const content_hash = sha256(new Uint8Array(buffer));
  out.push({
    json: { drive_file_id: base[i].json.id, nombre: base[i].json.name, content_hash },
    binary: items[i].binary,
  });
}
return out;

const vistos = new Set();
const out = [];
for (const a of $('Calcular hash').all()) {
  // Las cargas existentes también pasan a similitud y HITL para permitir reemplazos o renombrados aprobados.
  const cargaKey = `${a.json.drive_file_id}:${a.json.content_hash}:${String(a.json.nombre || '')}`;
  if (vistos.has(cargaKey)) continue;
  vistos.add(cargaKey);
  out.push({ json: a.json, binary: a.binary });
}
return out;

const archivos = $('Filtrar duplicados').all();
const textos = $input.all();
if (archivos.length !== textos.length) {
  throw new Error(`La cantidad de textos extraídos (${textos.length}) no coincide con los archivos (${archivos.length}).`);
}
return archivos.map((a, i) => {
  const t = String((textos[i] && textos[i].json && textos[i].json.text) || '').replace(/\s+/g, ' ').trim();
  if (!t) throw new Error(`No se pudo extraer texto del PDF "${a.json.nombre}"; se conserva la versión ya indexada.`);
  return { json: { ...a.json, query: t.slice(0, 1000) }, binary: a.binary };
});

const UMBRAL = 0.88;
const archivos = $('Primer fragmento').all();
const similares = {};
for (const r of $input.all()) {
  const idx = r.pairedItem && r.pairedItem.item !== undefined ? r.pairedItem.item : (Array.isArray(r.pairedItem) ? r.pairedItem[0].item : undefined);
  const doc = r.json.document || {};
  const score = Number(r.json.score);
  const id = doc.metadata && doc.metadata.drive_file_id;
  if (idx === undefined || !id || !(score >= UMBRAL)) continue;
  similares[idx] = { id, score };
}
return archivos.map((a, i) => ({
  json: {
    ...a.json,
    reemplazar_id: similares[i] ? similares[i].id : '__ninguno__',
    reemplazo_score: similares[i] ? similares[i].score : 0,
    requiere_revision_reemplazo: Boolean(similares[i]),
  },
  binary: a.binary,
}));

const raw = String($json.mensaje || '').trim();
const match = raw.match(/^(APROBAR|RECHAZAR)\s+HITL\s+([A-Z0-9-]+)/i);
if (!match) throw new Error('Comando HITL inválido. Usá APROBAR HITL <código> o RECHAZAR HITL <código>.');
return [{json: {
  hitl_request_id: match[2].toUpperCase(),
  human_decision: match[1].toUpperCase() === 'APROBAR' ? 'APPROVED' : 'REJECTED',
  canal: $json.canal,
  usuario_id: $json.usuario_id,
  mensaje: raw,
  received_at: new Date().toISOString(),
}}];

const requestId = $('HITL - Interpretar aprobación').first().json.hitl_request_id;
const decision = $('HITL - Interpretar aprobación').first().json.human_decision;
const now = Date.now();
const rows = $input.all().map(item => item.json);
const match = rows.reverse().find(row => String(row.Estado_Caso || '').startsWith(`HITL_PENDING|${requestId}|`));
if (!match) {
  return [{json: {status: 'not_found', respuesta: `No encontré una solicitud HITL pendiente con el código ${requestId}.`, requires_human: false}}];
}
const expires = String(match.Estado_Caso).split('|')[2];
if (!expires || Date.parse(expires) < now) {
  return [{json: {status: 'expired', respuesta: `La solicitud ${requestId} venció después de 30 minutos.`, requires_human: false}}];
}
return [{json: {
  status: decision === 'APPROVED' ? 'approved' : 'rejected',
  worker: 'HITL',
  respuesta: decision === 'APPROVED'
    ? `Solicitud ${requestId} aprobada. Revisá y enviá la respuesta propuesta del caso original.`
    : `Solicitud ${requestId} rechazada. El caso queda pendiente de corrección.`,
  requires_human: false,
  human_decision: decision,
  hitl_request_id: requestId,
  session_id: match.Session_ID || '',
}}];

const data = $json.data || {};
const expires = $('Preparar HITL / Unknown').first().json.hitl_expires_at;
const approved = data.approved === true;
const respondedAt = data.respondedAt || new Date().toISOString();
const expired = !expires || Date.parse(expires) < Date.parse(respondedAt);
const decision = expired ? 'EXPIRED' : (approved ? 'APPROVED' : 'REJECTED');
return [{json: {
  status: expired ? 'expired' : (approved ? 'approved' : 'rejected'),
  worker: 'HITL',
  respuesta: expired
    ? 'La solicitud de revisión humana venció después de 30 minutos.'
    : (approved
      ? 'La solicitud fue aprobada por el responsable en Slack y continuará por el flujo automático.'
      : 'La solicitud fue rechazada y queda derivada a revisión humana y contacto directo.'),
  requires_human: false,
  human_decision: decision,
  hitl_request_id: $('Preparar HITL / Unknown').first().json.hitl_request_id,
  session_id: $('Entrada multicanal').first().json.usuario_id,
  received_at: respondedAt,
  responder_id: data.responder && data.responder.id ? data.responder.id : '',
}}];

const decision = $('HITL - Preparar decisión Slack').first().json;
const classification = $('Normalizar clasificacion Router').first().json;
const input = $('Entrada multicanal').first().json;
return [{json: {
  ...classification,
  original_input: classification.original_input || input.mensaje,
  canal: input.canal,
  usuario_id: input.usuario_id,
  asunto: input.asunto,
  thread_ts: input.thread_ts,
  session_id: input.session_id || input.usuario_id,
  human_decision: decision.human_decision,
  hitl_request_id: decision.hitl_request_id,
}}];

